package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64            // PIC 9(1) @15 len=1
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string

var curRec SchedRec
var schedLines []string
var schedLineIdx int
var schedFileHandle *os.File

func main() {
	MainPara()
}

func MainPara() {
	openSchedFile()
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	closeSchedFile()
	fmt.Printf("SCHEDULES: %s\n", formatCount(WsCount))
}

func ReadPara() {
	if schedLineIdx >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	raw := schedLines[schedLineIdx]
	schedLineIdx++
	if len(raw) < 16 {
		raw = raw + strings.Repeat(" ", 16-len(raw))
	} else if len(raw) > 16 {
		raw = raw[:16]
	}
	curRec.ScAcct = raw[0:4]
	prinField := raw[4:11]
	rateField := raw[11:15]
	yearsField := raw[15:16]
	curRec.ScPrin = parseImpliedDecimal(prinField, 2)
	curRec.ScRate = parseImpliedDecimal(rateField, 2)
	yearsStr := strings.TrimSpace(yearsField)
	if yearsStr == "" {
		curRec.ScYears = 0
	} else {
		v, err := strconv.ParseInt(yearsStr, 10, 64)
		if err != nil {
			digits := ""
			for _, ch := range yearsStr {
				if ch >= '0' && ch <= '9' {
					digits += string(ch)
				}
			}
			if digits == "" {
				v = 0
			} else {
				v, _ = strconv.ParseInt(digits, 10, 64)
			}
		}
		curRec.ScYears = v
	}
}

func ProcessPara() {
	WsBal = curRec.ScPrin
	WsBal = truncHighOrder(WsBal, 8, 2)
	for WsYear = 1; WsYear <= curRec.ScYears; WsYear++ {
		rateDiv := curRec.ScRate.Shift(-2)
		one := decimal.NewFromInt(1)
		factor := one.Add(rateDiv)
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		WsBal = truncHighOrder(rounded, 8, 2)
		WsBalEd = formatEdited(WsBal, "ZZ,ZZZ,ZZ9.99")
		fmt.Printf("%s Y%s %s\n", curRec.ScAcct, formatYear(WsYear), WsBalEd)
	}
	WsBalEd = formatEdited(WsBal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s FINAL %s\n", curRec.ScAcct, WsBalEd)
	WsCount++
	WsCount = truncInt(WsCount, 2)
	ReadPara()
}

func openSchedFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open error: %v\n", err)
		os.Exit(1)
	}
	schedFileHandle = f
	reader := bufio.NewReader(f)
	for {
		line, err := reader.ReadString('\n')
		hasNL := false
		if len(line) > 0 && line[len(line)-1] == '\n' {
			line = line[:len(line)-1]
			hasNL = true
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
		}
		if err == io.EOF && line == "" && !hasNL {
			break
		}
		schedLines = append(schedLines, line)
		if err == io.EOF {
			break
		}
		if err != nil && err != io.EOF {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
	}
}

func closeSchedFile() {
	if schedFileHandle != nil {
		schedFileHandle.Close()
	}
}

func parseImpliedDecimal(s string, scale int32) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	cleaned := strings.ReplaceAll(trimmed, " ", "")
	if cleaned == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(cleaned)
	if err != nil {
		digits := ""
		for _, ch := range cleaned {
			if ch >= '0' && ch <= '9' {
				digits += string(ch)
			} else if ch == '-' {
				digits += string(ch)
			}
		}
		if digits == "" || digits == "-" {
			return decimal.NewFromInt(0)
		}
		d, _ = decimal.NewFromString(digits)
	}
	return d.Shift(-scale)
}

func truncHighOrder(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if v.IsZero() {
		return v
	}
	neg := v.IsNegative()
	absVal := v.Abs()
	scaled := absVal.Shift(scale).Truncate(0)
	totalDigits := intDigits + int(scale)
	s := scaled.StringFixed(0)
	if len(s) > totalDigits {
		s = s[len(s)-totalDigits:]
	}
	if s == "" {
		s = "0"
	}
	d, err := decimal.NewFromString(s)
	if err != nil {
		d = decimal.NewFromInt(0)
	}
	res := d.Shift(-scale)
	if neg {
		res = res.Neg()
	}
	return res
}

func truncInt(val int64, digits int) int64 {
	if digits <= 0 {
		return val
	}
	pow := int64(1)
	for i := 0; i < digits; i++ {
		pow *= 10
	}
	if val < 0 {
		abs := -val
		abs = abs % pow
		return -abs
	}
	if val >= pow {
		return val % pow
	}
	return val
}

func formatEdited(v decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracDigits++
		}
	}
	neg := v.IsNegative()
	absVal := v.Abs()
	scaled := absVal.Shift(int32(fracDigits)).Truncate(0)
	pow10Frac := decimal.New(1, int32(fracDigits))
	intPartDec := scaled.Shift(-int32(fracDigits)).Truncate(0)
	fracPartDec := scaled.Sub(intPartDec.Mul(pow10Frac))

	intStrFull := intPartDec.StringFixed(0)
	var intStr string
	if len(intStrFull) > intDigits {
		intStr = intStrFull[len(intStrFull)-intDigits:]
	} else {
		intStr = strings.Repeat("0", intDigits-len(intStrFull)) + intStrFull
	}
	fracStrFull := fracPartDec.StringFixed(0)
	fracStr := ""
	if fracDigits > 0 {
		if len(fracStrFull) > fracDigits {
			fracStr = fracStrFull[len(fracStrFull)-fracDigits:]
		} else {
			fracStr = strings.Repeat("0", fracDigits-len(fracStrFull)) + fracStrFull
		}
	}

	out := []byte(picture)
	intIdx := 0
	fracIdx := 0
	suppressed := true
	for i := 0; i < len(picture); i++ {
		ch := picture[i]
		if ch == 'Z' || ch == '9' {
			isInt := dotPos == -1 || i < dotPos
			if isInt {
				digit := intStr[intIdx]
				intIdx++
				if suppressed {
					if ch == 'Z' && digit == '0' {
						out[i] = ' '
					} else {
						out[i] = digit
						suppressed = false
					}
				} else {
					out[i] = digit
				}
			} else {
				digit := fracStr[fracIdx]
				fracIdx++
				out[i] = digit
			}
		} else if ch == ',' {
			if suppressed {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if ch == '.' {
			out[i] = '.'
		} else {
			out[i] = ch
		}
	}
	if neg {
		for i := 0; i < len(out); i++ {
			if out[i] >= '0' && out[i] <= '9' {
				if i > 0 && out[i-1] == ' ' {
					out[i-1] = '-'
				} else if out[0] == ' ' {
					out[0] = '-'
				}
				break
			}
		}
	}
	return string(out)
}

func formatYear(v int64) string {
	v = v % 100
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

func formatCount(v int64) string {
	v = v % 100
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}
